/**
 * Repairs markdown that is mid-stream: closes unclosed bold/italic/strikethrough
 * markers and unterminated inline code / code fences so partial chunks render
 * without flickering or broken syntax.
 *
 * Deliberately conservative — only appends closing characters, never rewrites content.
 */
export function closeIncompleteMarkdown(markdown: string): string {
  let text = markdown;

  // Close an unterminated fenced code block (odd number of ``` lines).
  const fenceMatches = text.match(/^`{3,}/gm);
  if (fenceMatches && fenceMatches.length % 2 === 1) {
    text = `${text}\n\`\`\``;
  }

  // Inline constructs are only repaired outside of code fences for simplicity:
  // if we just opened a fence, the remainder is code and should not be touched.
  const firstFence = text.indexOf('```');
  const hasUnclosedFence = fenceMatches !== null && fenceMatches.length % 2 === 1;
  const prose = hasUnclosedFence && firstFence !== -1 ? text.slice(0, firstFence) : text;
  const rest = hasUnclosedFence && firstFence !== -1 ? text.slice(firstFence) : '';

  let repaired = prose;
  // Count unescaped emphasis markers; close whichever are odd.
  for (const marker of ['**', '__', '~~']) {
    const occurrences = prose.split(marker).length - 1;
    if (occurrences % 2 === 1) {
      repaired += marker;
    }
  }
  // Single asterisk/underscore italics.
  for (const marker of ['*', '_']) {
    // Only count markers not part of **/__ pairs by stripping doubles first.
    const singles = repaired.replace(/\*\*/g, '').replace(/__/g, '').split(marker).length - 1;
    if (singles % 2 === 1) {
      repaired += marker;
    }
  }
  // Inline code.
  const backtickCount = repaired.replace(/```/g, '').split('`').length - 1;
  if (backtickCount % 2 === 1) {
    repaired += '`';
  }

  return repaired + rest;
}

export { Response } from './Response';
export type { ResponseProps } from './Response';
export { closeIncompleteMarkdown } from './close-incomplete-markdown';

'use client';

import * as React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { cn } from '@/lib/utils';
import { CodeBlock } from '../code-block';
import { closeIncompleteMarkdown } from './close-incomplete-markdown';

export interface ResponseProps {
  /** Markdown content to render. */
  children: string;
  /**
   * Repair unclosed emphasis/inline-code/fences while streaming so partial
   * chunks render cleanly (default true).
   */
  parseIncompleteMarkdown?: boolean;
  className?: string;
}

/**
 * Streaming-optimized markdown renderer for AI responses.
 *
 * Wraps react-markdown with GFM support and routes fenced code blocks to
 * the CodeBlock component for highlighting + copy.
 */
const Response = React.forwardRef<HTMLDivElement, ResponseProps>(
  ({ children, parseIncompleteMarkdown = true, className, ...props }, ref) => {
    const content = React.useMemo(
      () => (parseIncompleteMarkdown ? closeIncompleteMarkdown(children) : children),
      [children, parseIncompleteMarkdown]
    );

    return (
      <div
        ref={ref}
        className={cn(
          'text-sm space-y-3 [&_a]:text-primary [&_a]:underline underline-offset-2',
          '[&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5',
          '[&_h1]:text-lg [&_h1]:font-semibold [&_h2]:text-base [&_h2]:font-semibold',
          '[&_h3]:text-sm [&_h3]:font-semibold',
          '[&_blockquote]:border-l-2 [&_blockquote]:border-border [&_blockquote]:pl-3 [&_blockquote]:text-muted-foreground',
          '[&_table]:w-full [&_table]:text-xs [&_th]:border [&_th]:border-border [&_th]:p-1.5 [&_td]:border [&_td]:border-border [&_td]:p-1.5',
          className
        )}
        {...props}
      >
        <ReactMarkdown
          remarkPlugins={[remarkGfm]}
          components={{
            pre: ({ children }) => <>{children}</>,
            code: ({ className: codeClassName, children: codeChildren }) => {
              const raw = String(codeChildren).replace(/\n$/, '');
              const match = /language-(\w+)/.exec(codeClassName ?? '');
              const isInline = !match && !raw.includes('\n');
              if (isInline) {
                return (
                  <code className="bg-muted px-1 py-0.5 rounded text-xs font-mono before:content-none after:content-none">
                    {raw}
                  </code>
                );
              }
              return <CodeBlock code={raw} language={match?.[1] ?? 'text'} />;
            },
          }}
        >
          {content}
        </ReactMarkdown>
      </div>
    );
  }
);
Response.displayName = 'Response';

export { Response };

{
  "id": "response",
  "name": "Response",
  "tier": "molecule",
  "description": "Streaming-optimized markdown renderer for AI responses with GFM support, streaming-safe repair of incomplete syntax, and highlighted code blocks with copy.",
  "designIntent": "Render AI output as rich content without flicker or broken partial syntax while tokens arrive.",
  "props": [
    {
      "name": "children",
      "type": "string",
      "required": true,
      "description": "Markdown content to render."
    },
    {
      "name": "parseIncompleteMarkdown",
      "type": "boolean",
      "defaultValue": true,
      "required": false,
      "description": "Close unclosed emphasis/inline-code/fences during streaming."
    }
  ],
  "examples": [
    {
      "title": "Basic response",
      "code": "<Response>{assistantMessage.content}</Response>"
    },
    {
      "title": "Inside Message",
      "code": "<Message message={m} renderContent={(c) => <Response>{c}</Response>} />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not use Response inside a code fence context",
      "explanation": "Response is the top-level renderer; nested Response instances double-parse content."
    }
  ],
  "accessibility": [
    {
      "feature": "Semantic HTML",
      "implementation": "Headings, lists and tables are real elements announced correctly."
    },
    {
      "feature": "Code blocks",
      "implementation": "Routed through CodeBlock with accessible copy button."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
